// Only run if both dates exist
      if (ctx.Account_Opened_Date != null && ctx.transaction_date != null) {
        def fmt = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd");

        // Parse dates as LocalDate
        def opened = java.time.LocalDate.parse(ctx.Account_Opened_Date, fmt);
        def txn    = java.time.LocalDate.parse(ctx.transaction_date, fmt);

        // Ignore if transaction happens before the account was opened
        if (!txn.isBefore(opened)) {
          // Full years elapsed between the two dates
          long years = java.time.temporal.ChronoUnit.YEARS.between(opened, txn);

          // How many full 4-year intervals have passed
          if (years >= 4) {
            long intervals = years / 4L;   // integer division
            ctx.Card_Renewed = intervals;
          }
        }
      }

if (ctx.Account_Opened_Date != null && ctx.transaction_date != null) {
        def fmt = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd");

        def opened = java.time.LocalDate.parse(ctx.Account_Opened_Date, fmt);
        def txn    = java.time.LocalDate.parse(ctx.transaction_date, fmt);

        // Ignore if transaction is before account open
        if (!txn.isBefore(opened)) {

          long intervals = 0;
          def renewal = opened.plusYears(4L);

          // Walk forward in 4-year jumps, as long as the renewal date is <= transaction date
          while (!renewal.isAfter(txn)) {
            intervals += 1;

            // e.g. Date_Renewed_1, Date_Renewed_2, ...
            ctx["Date_Renewed_" + intervals] = renewal.format(fmt);

            renewal = renewal.plusYears(4L);
          }

          if (intervals > 0) {
            ctx.Card_Renewed = intervals;
          }
        }
      }
